<?php $f=$catalogFilters;$filterCount=($f['tip']!=='all')+($f['gen']!=='')+($f['de']>1880)+($f['pana']<2100)+($f['nota']>0)+($f['q']!==''); ?>
<section class="content listing-intro"><span class="section-kicker">Găsește următoarea poveste</span><div class="section-head"><div><h1><?=e($heading)?></h1><p><?=e(ro_number($total))?> titluri pentru selecția ta</p></div><button class="ghost-btn filter-toggle" type="button" aria-expanded="false" aria-controls="catalogFilters"><?=icon('filter')?> Filtre<?=$filterCount?' ('.$filterCount.')':''?></button></div>
<form class="catalog-filters" id="catalogFilters" action="/catalog/" method="get"><?php if(($f['adaugate']??'')==='azi'):?><input type="hidden" name="adaugate" value="azi"><?php endif;?><div class="filter-heading"><strong>Filtrează catalogul</strong><button class="icon-btn" type="button" data-close-filters aria-label="Închide filtrele"><?=icon('close')?></button></div>
<label>Tip<select name="tip"><?php foreach(['all'=>'Filme și seriale','movies'=>'Filme','tv'=>'Seriale'] as $v=>$label):?><option value="<?=e($v)?>"<?=$f['tip']===$v?' selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label>Gen<select name="gen"><option value="">Toate genurile</option><?php foreach(genre_map() as $g=>$info):?><option value="<?=e($g)?>"<?=$f['gen']===$g?' selected':''?>><?=e(genre_label($g))?></option><?php endforeach;?></select></label>
<label>Din anul<input name="de" type="number" min="1880" max="2100" value="<?=$f['de']>1880?(int)$f['de']:''?>" placeholder="Oricare"></label><label>Până în anul<input name="pana" type="number" min="1880" max="2100" value="<?=$f['pana']<2100?(int)$f['pana']:''?>" placeholder="Oricare"></label>
<label>Rating minim<select name="nota"><?php $ratingOptions=array_unique([0,5,6,7,8,9,$f['nota']]);sort($ratingOptions);foreach($ratingOptions as $n):?><option value="<?=$n?>"<?=(float)$f['nota']===$n*1.0?' selected':''?>><?=$n?$n.'+ IMDb':'Oricare'?></option><?php endforeach;?></select></label>
<label>Ordonează<select name="sort"><?php foreach(['recent'=>'Recent adăugate','year'=>'Anul lansării','rating'=>'Rating IMDb'] as $v=>$label):?><option value="<?=$v?>"<?=$f['sort']===$v?' selected':''?>><?=$label?></option><?php endforeach;?></select></label>
<label class="filter-query">Titlu<input name="q" type="search" value="<?=e($f['q'])?>" placeholder="Caută în selecție"></label><div class="filter-actions"><button class="primary-btn" type="submit">Aplică filtrele</button><a class="text-btn" href="/catalog/">Resetează</a></div></form>
<?php if($filterCount):?><div class="active-filters" aria-label="Filtre active"><?php foreach(['tip','gen','de','pana','nota','q'] as $key):$v=$f[$key];if(($key==='tip'&&$v==='all')||($key==='de'&&$v===1880)||($key==='pana'&&$v===2100)||$v===''||($key==='nota'&&$v==0))continue;$clear=$f;unset($clear[$key]);$label=$key==='gen'?genre_label($v):($key==='tip'?($v==='tv'?'Seriale':'Filme'):($key==='de'?'Din ':($key==='pana'?'Până în ':($key==='nota'?'IMDb ≥ ':''))).$v);?><a href="<?=e(catalog_link($clear))?>" aria-label="Elimină filtrul <?=e($label)?>"><?=e($label)?> <?=icon('close')?></a><?php endforeach;?><a class="text-btn" href="/catalog/">Șterge toate</a></div><?php endif;?>
<?php if(($f['adaugate']??'')==='azi'):?><p class="catalog-note">Titluri adăugate astăzi pe site, după ora României. Lista se actualizează după fiecare import verificat.</p><?php elseif($f['sort']==='recent'):?><p class="catalog-note">Titlurile cu dată de adăugare cunoscută apar primele; celelalte sunt ordonate după anul lansării.</p><?php endif;?>
</section><section class="content catalog-results"><?php if(!empty($catalogDoc['unavailable'])):?><div class="status"><h2>Catalogul se actualizează</h2><p>Filtrarea completă nu este disponibilă momentan. Poți explora în continuare filmele și serialele.</p><a class="primary-btn" href="/filme/">Descoperă filme</a></div><?php elseif($items):include __DIR__.'/grid.php';else:?><div class="status"><h2>Niciun titlu pentru aceste filtre</h2><p>Încearcă un interval mai larg sau elimină un filtru.</p><a class="primary-btn" href="/catalog/">Resetează filtrele</a></div><?php endif;?>
<?php if($pages>1):?><nav class="pagination" aria-label="Pagini catalog"><?php if($page>1):?><a href="<?=e(catalog_link($f,$page-1))?>" aria-label="Pagina precedentă">‹</a><?php endif;?><?php foreach(pagination_window($page,$pages) as $p):if($p==='…'):?><span>…</span><?php else:?><a href="<?=e(catalog_link($f,$p))?>"<?=$p==$page?' class="active" aria-current="page"':''?>><?=$p?></a><?php endif;endforeach;?><?php if($page<$pages):?><a href="<?=e(catalog_link($f,$page+1))?>" aria-label="Pagina următoare">›</a><?php endif;?></nav><?php endif;?></section>
